@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Milwaukee Bucks DNA — Hunter green and cream city, fear the deer. */
.theme-milwaukee-bucks {
  --bg: oklch(0.276 0.056 159.8);
  --surface: oklch(0.343 0.074 158.6);
  --surface-2: oklch(0.408 0.089 158.4);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.812 0.171 158.9);
  --accent: oklch(0.619 0.134 156.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.913 0.038 85.3);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-milwaukee-bucks h1,
.theme-milwaukee-bucks h2,
.theme-milwaukee-bucks h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-milwaukee-bucks { --font-ui: var(--font-display); }
.theme-milwaukee-bucks h1, .theme-milwaukee-bucks h2 { text-transform: uppercase; font-weight: 800; }
.theme-milwaukee-bucks h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-milwaukee-bucks button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }
.theme-milwaukee-bucks th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.1em; font-size: 12px; }
.theme-milwaukee-bucks tbody tr:hover { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-milwaukee-bucks ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-milwaukee-bucks { --fg: oklch(0.93 0.02 90); } .theme-milwaukee-bucks h1 { color: #eee1c6; } .theme-milwaukee-bucks h1::after { background: linear-gradient(90deg, #2a9d63 0 50%, #eee1c6 50% 100%); }

/* alt mode: Association Edition white */
.theme-milwaukee-bucks.alt-mode {
  --bg: oklch(0.98 0.001 260); --surface: oklch(1 0 0); --surface-2: oklch(0.94 0.002 260);
  --fg: oklch(0.2 0.005 260); --fg-muted: oklch(0.45 0.005 260); --line: oklch(0.89 0.003 260);
  --accent: oklch(0.619 0.134 156.3); --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.68 0.09 85.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%); --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%); --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-milwaukee-bucks.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: oklch(0.619 0.134 156.3); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
